// ===== Конфигурация =====
const VALID_KEYS = ["secret-key-1", "secret-key-2"];
const LIMIT_PER_MIN = 3;
const WINDOW_MS = 60 * 1000;

// ===== Читаем ключ из заголовка =====
const key = msg.req.headers["x-api-key"];

if (!key) {
    msg.statusCode = 401;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = {
        error: "Unauthorized",
        message: "Заголовок X-API-Key отсутствует"
    };
    return [null, msg];
}

if (!VALID_KEYS.includes(key)) {
    msg.statusCode = 401;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = {
        error: "Unauthorized",
        message: "Неверный API-ключ"
    };
    return [null, msg];
}

// ===== Rate limit =====
const now = Date.now();
const storeKey = `rl_${key}`;
let state = flow.get(storeKey) || { count: 0, windowStart: now };

// Окно истекло — сбрасываем
if (now - state.windowStart > WINDOW_MS) {
    state = { count: 0, windowStart: now };
}

state.count += 1;
flow.set(storeKey, state);

if (state.count > LIMIT_PER_MIN) {
    const retryAfter = Math.ceil((state.windowStart + WINDOW_MS - now) / 1000);
    msg.statusCode = 429;
    msg.headers = {
        "Content-Type": "application/json; charset=utf-8",
        "Retry-After": String(retryAfter),
        "X-RateLimit-Limit": String(LIMIT_PER_MIN),
        "X-RateLimit-Remaining": "0"
    };
    msg.payload = {
        error: "Too Many Requests",
        message: `Лимит ${LIMIT_PER_MIN} запросов в минуту превышен`,
        retryAfter: retryAfter
    };
    return [null, msg];
}

// ===== Успех =====
msg.headers = {
    "Content-Type": "application/json; charset=utf-8",
    "X-RateLimit-Limit": String(LIMIT_PER_MIN),
    "X-RateLimit-Remaining": String(LIMIT_PER_MIN - state.count),
    "X-API-Key-Used": key
};
msg.statusCode = 200;
msg.payload = {
    message: "Доступ разрешён",
    key: key,
    used: state.count,
    remaining: LIMIT_PER_MIN - state.count
};
return [msg, null];
